head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_LOW_CTG_ALW = "표준산업업종 중 소분류 항목만 선택가능합니다.";
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar, scwin.strSch;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let arrPar = new Array();
        window.document.body.scroll = "no";

        /***************************************
        opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
        opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
         ***************************************/
        scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
        scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arrPar);
            scwin.strSch = (arrPar.length > 1 ? arrPar[0] : "");
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92006.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_IndustryList_OnLoadError
 * @description dts_IndustryList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IndustryList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_IndustryList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92006.dts_IndustryList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IndustryList_OnLoadCompleted
 * @description dts_IndustryList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IndustryList_OnLoadCompleted = async function(rowcount) {
    try {
        let arrPar = new Array();
        if (dts_IndustryList.errorMsg) {
            await $c.win.alert(dts_IndustryList.errorMsg);
        } else {
            txb_TotCnt.setValue("총 " + rowcount + " 건");

            /*
    		if (js_market == '2') {
    MxGrid_1.setColumnProp("STD_IND_CD", "Show",false) ;
    MxGrid_1.setColumnProp("KOSDAQ_STD_IND_CD", "Show",true) ;
    		} else if (js_market == '1') {
    MxGrid_1.setColumnProp("STD_IND_CD", "Show",true) ;
    MxGrid_1.setColumnProp("KOSDAQ_STD_IND_CD", "Show",false) ;
    MxGrid_1.setColumnProp('STD_IND_CD','Mask',"XX-XX-XX") ;
    		}
             */
            $c.cm.setColumnProp(MxGrid_1, 'STD_IND_CD', 'Mask', "XX-XX-XX");

            // 초기1회 초기값으로 설정된 업종코드를 검색한다.
            if (scwin.strSch !== "") {
                for (let i = 1; i <= dts_IndustryList.getRowCount(); i++) {
                    if (scwin.strSch === dts_IndustryList.getCellData(i, 1)) {
                        // 찾아야할 코드를 발견했을 경우
                        dts_IndustryList.setRowPosition(i, 0);
                        break;
                    }
                }
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92006.dts_IndustryList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92006.img_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92006.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92006.img_Close_onclick" });
    }
};

/**
 * @method
 * @name MxGrid_1_OnDblClick
 * @description MxGrid_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxGrid_1_OnDblClick = async function(row, colid) {
    try {
        let arrPar = new Array();
        const gRow = dts_IndustryList.getRowPosition();
        let gVal = "";

        /*
        	if ( js_market == '1' ) {

        		gVal = dts_IndustryList.NameValue(gRow, "STD_IND_CD");
        		if ( gVal.substr(4, 2) == "00" ) {
        			alert( MSG_LOW_CTG_ALW );
        			return;
        		}

        	} else if  (js_market == '2' ) {

        		gVal = dts_IndustryList.NameValue(row, "KOSDAQ_STD_IND_CD");
        		if (gVal.length != 7 ) {
        			alert( MSG_LOW_CTG_ALW );
        			return;
        		}
        	}
         */
        gVal = dts_IndustryList.getCellData(gRow, "STD_IND_CD");
        if (gVal.substr(4, 2) === "00") {
            await $c.win.alert(scwin.MSG_LOW_CTG_ALW);
            return;
        }
        if (scwin.fn_SetPar !== undefined) {
            arrPar[0] = {
                STD_IND_CD: dts_IndustryList.getCellData(gRow, "STD_IND_CD"),
                IND_NM: dts_IndustryList.getCellData(gRow, "IND_NM")
                // ,KOSDAQ_STD_IND_CD: dts_IndustryList.NameValue(gRow, "KOSDAQ_STD_IND_CD")
            };
            scwin.fn_SetPar(arrPar);
        }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92006.MxGrid_1_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_IndustryList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_IndustryList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
